from pathlib import Path
import pandas as pd


def leggi_misure(cartella):
    parti = []
    for f in sorted(Path(cartella).glob("*.csv")):
        df = pd.read_csv(f, sep=";")
        df.insert(0, "pezzo", f.stem)
        parti.append(df)
    return pd.concat(parti, ignore_index=True)

def capacita(df, specifiche):
    righe = []
    for q, g in df.groupby("quota"):
        nom, ti, ts = specifiche[q]
        lsl, usl = nom + ti, nom + ts
        m, s = g["valore"].mean(), g["valore"].std()
        righe.append({"quota": q, "media": m, "std": s, "Cp": (usl - lsl) / (6 * s), "Cpk": min(usl - m, m - lsl) / (3 * s)})
    return pd.DataFrame(righe).set_index("quota")

from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill


def scrivi_report(dettaglio, cap, file):
    wb = Workbook()
    ws = wb.active
    ws.title = "Misure"
    ws.append(list(dettaglio.columns))
    rosso = PatternFill("solid", fgColor="FFC7CE")
    for riga in dettaglio.itertuples(index=False):
        ws.append([v.item() if hasattr(v, "item") else v for v in riga])
        if not riga.ok:
            for c in ws[ws.max_row]:
                c.fill = rosso
    ws2 = wb.create_sheet("Capacità")
    ws2.append(["quota", *cap.columns])
    for q, r in cap.iterrows():
        ws2.append([q, *[round(float(x), 4) for x in r]])
    for foglio in (ws, ws2):
        for c in foglio[1]:
            c.font = Font(bold=True)
    wb.save(file)
